mapper.select:
select mgs.goods_id, mgs.common_id, mgb.goods_name, mgs.goods_stock, mgs.goods_alarm, mgb.goods_image, mgb.goods_spec, mgs.create_time, mgs.update_time from ${database.prefix.goods}hou_goods_stock mgs left join ${database.prefix.goods}hou_goods_base mgb on mgs.goods_id = mgb.goods_id left join ${database.prefix.goods}hou_goods_common mgc on mgc.common_id = mgb.common_id left join storage_goods_base stgb on mgs.goods_id = stgb.goods_id left join storage_info si on stgb.storage_id = si.storage_id where mgb.shop_id = #{param.shopId} and mgb.is_delete = 0 and mgc.common_state != 3 and mgc.is_delete = 0
and mgb.goods_name = #{param.goodsName}
and si.storage_name like concat('%',#{param.storageName},'%')
and mgs.update_time between #{param.startTime} and #{param.endTime}
and mgs.goods_stock <= mgs.goods_alarm
#{item}
group by mgs.goods_id
